mapper.select:
SELECT *
FROM ws_offline_message
WHERE user_type = #{userType}
  AND user_id = #{userId}
  AND sent = 0
  AND deleted = 0
  AND (expire_time IS NULL OR expire_time > NOW())
  AND retry_count < max_retry_count
ORDER BY create_time
LIMIT #{limit}

mapper.update:
UPDATE ws_offline_message SET sent = 1, send_time = #{sendTime}, updater = 'system', update_time = NOW() WHERE id IN
#{id}
AND sent = 0 AND deleted = 0
